const children = browslessRefData('workflow') || {};
const results = Object.fromEntries(Object.entries(children).map(([id, child]) => [id, { ...(child.variables?.result || { passed: false }), packageReturned: child.variables?.packageReturned === true }]));
browslessSetVariable('results', results);
browslessSetVariable('allPassed', Object.keys(results).length === 6 && Object.values(results).every(result => result.passed === true && result.packageReturned));
browslessNextBlock([], false);

const checks = {
  ...(browslessRefData('variables', 'result')?.checks || {}),
  "submitted": Boolean(document.querySelector('#form-status').textContent === 'Profile submitted successfully.'),
  "name": Boolean(JSON.parse(document.querySelector('#form-result').textContent).fullName === 'Alex Morgan'),
  "country": Boolean(JSON.parse(document.querySelector('#form-result').textContent).country === 'PL'),
  "plan": Boolean(JSON.parse(document.querySelector('#form-result').textContent).plan === 'pro'),
  "interests": Boolean(JSON.stringify(JSON.parse(document.querySelector('#form-result').textContent).interests) === JSON.stringify(['automation', 'testing']))
};
const passed = Object.values(checks).every(Boolean);
browslessSetVariable('result', { passed, checks });
if (!passed) {
  console.error('Playground checks failed', checks);
}
browslessNextBlock([], false);

